			CameraController.ShakeCamera(0.15f);
		}
		else
		{
			CreateFireCross((!parent.isFacingRight) ? Globals.GetPerpendicular(inputVector, parent.forehandAnimPlayed) : Globals.GetPerpendicular(inputVector, !parent.forehandAnimPlayed));
