public class NegMeleeState(string newName, FSM newFSM, Player newPlayer) : MeleeAttackState(newName, newFSM, newPlayer)
{
	public delegate void ChargeEventHandler(Player player, NegMeleeState negMeleeState);
	public bool useCastBar = true;
	public SyncedNumVarStat chargeTimeStat = new SyncedNumVarStat(0.3f);
	public int chargeStopwatchID;
	public bool isCharged;
	public bool useBaseMAS;
	public bool allowCharge = true;
	public float chargeAtkMoveSpeed = 1f;
	public static ChargeEventHandler chargeEventHandlers;
	public float ChargePercentage => ChaosStopwatch.GetTimePercentage(chargeStopwatchID);
	public void NegPreCheck()
	{
		if (fsm.previousStateName != fsm.currentStateName)
		{
			comboCounter = 1;
		}
		useBaseMAS = !allowCharge || (autoHoldStat.CurrentValue && ((!repeatFinalHit && comboCounter < maxComboCount) || (repeatFinalHit && comboCounter < maxComboCount - 1)));
		holdReleased = false;
		attackExecuted = false;
		isCharged = false;
	}
	public override void OnEnter()
	{
		NegPreCheck();
		base.OnEnter();
		if (!useBaseMAS)
		{
			chargeStopwatchID = ChaosStopwatch.Begin(chargeTimeStat.CurrentValue);
			if (useCastBar)
			{
				parent.hud.castBar.StartCast(chargeStopwatchID, givenStatus: true);
			}
		}
	}
	public override bool MovementCheck()
	{
		if (useBaseMAS)
		{
			return base.MovementCheck();
		}
		movementVector = ((!base.MovementCheck()) ? Vector2.zero : inputVector);
		parent.movement.moveVector = movementVector;
		return false;
	}
	public override void Update()
	{
		if (useBaseMAS)
		{
			base.Update();
			return;
		}
		if (!holdReleased)
		{
			HandleHoldButton();
			if (!holdReleased)
			{
				return;
			}
			parent.hud.castBar.EndCast();
		}
		if (!attackExecuted)
		{
			if (parent.anim.AnimPlayed(animExecTime))
			{
				attackExecuted = true;
				ExecuteAttack();
				SetRepeatLock(setLock: false);
			}
		}
		else
		{
			ExitToSkillOrRunOrIdle();
		}
	}
	public override void HandleHoldButton()
	{
		if (isCharged)
		{
			OnCharged();
			if (chargeEventHandlers != null)
			{
				chargeEventHandlers(parent, this);
			}
			holdReleased = true;
		}
		else
		{
			isCharged = ChaosStopwatch.Check(chargeStopwatchID);
		}
		if (!holdReleased)
		{
			holdReleased = !parent.inputDevice.GetButton("Skill" + skillSlot);
		}
		parent.anim.PlayDirectional(OnHoldAnimStr, -1, (!holdReleased) ? animHoldTime : animStartTime);
	}
	public override void ExecuteAttack()
	{
		if (useBaseMAS)

			if (useBaseMAS)
			{
				base.ExecuteAttack();
				return;
			}
			if (isCharged)
			{
				movementVector = inputVector;
				parent.movement.moveVector = movementVector;
				parent.movement.MoveToMoveVector(chargeAtkMoveSpeed);
			}
			else
			{
				parent.movement.MoveToMoveVector();
			}
			parent.hud.castBar.EndCast();
			holdReleased = true;
			attackExecuted = true;
			base.ExecuteAttack();
		}
		public override void OnExit()
		{
			base.OnExit();
			if (!useBaseMAS && useCastBar)
			{
				parent.hud.castBar.EndCast();
			}
		}
		public override bool ExitToSkillOrRunOrIdle()
		{
			if (useBaseMAS)
			{
				return base.ExitToSkillOrRunOrIdle();
			}
			currentAnimTime = parent.anim.GetAnimTime();
			if (currentAnimTime >= cancelThreshold && parent.HandleSkills(allowButtonHeld: true, string.Empty))
			{
				return true;
			}
			if (currentAnimTime >= runThreshold && GetInputVector(faceInputVector: false, useAimVector: false, ignoreZero: false) != Vector2.zero)
			{
				fsm.ChangeState("Run");
				return true;
			}
			if (currentAnimTime >= exitThreshold)
			{
				fsm.ChangeState(fsm.defaultStateName);
				return true;
			}
			return false;
		}
		public override void PlayAnimation(int attackCount)
		{
			if (useBaseMAS || !holdReleased)
			{
				base.PlayAnimation(attackCount);
			}
		}
		public virtual void OnCharged()
		{
		}
	}
