		if (ChaosStopwatch.Check(durationStopwatchID) || followTrans == null || (parentEntity != null && parentEntity.fsm.currentStateName.Contains("Dead")))
		{
			destroyQueued = true;
			Object.Destroy(gameObject, 1f);
			attack.gameObject.SetActive(value: false);
			fireSys.Stop();
