using UnityEngine;
public class FireMine : Projectile
{
	private static GameObject prefab;
	public Vector2 originalVector;
	public Vector2 targetVector;
	private ChaosQuickStopwatch changeStopwatch = new ChaosQuickStopwatch(0.75f);
	private float changeLerpValue;
	private bool changeCompleted;
	public ParticleSystem firePartSys;
	public ParticleEffect smokeEmitter;
	public bool smokePlaying;
	public static GameObject Prefab => prefab ?? (prefab = ChaosBundle.Get("Assets/Prefabs/AreaEffects/FireMine.prefab"));
	public override void Start()
	{
		base.Start();
		anim.Play("Spawn", -1, 0f);
		changeStopwatch.IsRunning = true;
		originalVector = moveVector;
		targetVector = (2f * targetVector - originalVector).normalized;
		smokeEmitter = PoolManager.GetPoolItem<ParticleEffect>("SmokeEmitter");
		smokeEmitter.followTransform = transform;
		smokeEmitter.transform.position = transform.position;
	}
	public override void FixedUpdate()
	{
		base.FixedUpdate();
		if (!changeCompleted)
		{
			changeLerpValue = changeStopwatch.TimePercentage;
			changeCompleted = changeLerpValue >= 1f;
			isPointedAtMoveVector = changeCompleted;
			moveVector = Vector2.Lerp(originalVector, targetVector, changeLerpValue);
			moveSpeed = Mathf.Lerp(4f, 32f, changeLerpValue);
			attackBox.knockbackOverwriteVector = moveVector;
		}
		else if (!smokePlaying)
		{
			smokePlaying = true;
			smokeEmitter.Play(90f);
		}
	}
	public override void HandleWallCollision(Collider2D other)
	{
		if (changeCompleted || changeLerpValue > 0.5f)
		{
			base.HandleWallCollision(other);
			return;
		}
		rigidbody2D.velocity = Vector2.zero;
		originalVector = Vector2.zero;
	}
	public override void ResetProjectile()
	{
		if (firePartSys != null)
		{
			firePartSys.transform.SetParent(transform.parent);
			firePartSys.Stop();
			Object.Destroy(firePartSys.gameObject, 1f);
		}
		if (smokeEmitter != null)
		{
			smokeEmitter.Stop();
		}
		FireExplosion.SpawnExplosion(transform.position, 0.5f, 0.5f);
		string audioID = "FireArcEnd";
		Vector2? soundOrigin = transform.position;
		float overridePitch = Random.Range(1f, 1.1f);
		SoundManager.PlayAudioWithDistance(audioID, soundOrigin, null, 24f, -1f, overridePitch);
		base.ResetProjectile();
	}
