	public int atkHitCount = 6;
	private float atkInterval = 0.125f;
	private int atkStopwatchID;
	public bool atkCompleted;
	private int hitCounter;
	public int finalAttackLevel = 3;
	private Vector2 currentPosition;
	public static GameObject Prefab => prefab ?? (prefab = ChaosBundle.Get("Assets/Prefabs/AreaEffects/CircleBurner.prefab"));
	private void Start()
	{
		hitCounter = 0;
		partSysMain = flamePartSys.main;
		if (isEmpowered)
		{
			atkHitCount += 2;
		}
		atkStopwatchID = ChaosStopwatch.Begin(0f, useInterval: true, atkInterval, atkHitCount);
