	{
		if (atkCompleted)
		{
			return;
		}
		switch (ChaosStopwatch.CheckInterval(atkStopwatchID))
		{
		case StopwatchState.Running:
			atkCollider.enabled = false;
			break;
		case StopwatchState.Ready:
			hitCounter++;
			if (hitCounter == atkHitCount)
			{
				attack.ChangeAttackInfoLevel(finalAttackLevel);
				partSysMain.startSpeed = 16f;
				flameEndPartSys.Emit(100);
				atkCollider.radius = 3.75f;
