	{
		BaseOnEnter();
		base.ExecuteSkill();
		finishedDashing = false;
		if (isUltimate)
		{
			parent.movement.dashDurationStat.AddMod(ultDashMod);
			parent.movement.dashTimer = ultDashMod.modValue;
		}
		else
		{
			parent.movement.dashDurationStat.AddMod(baseDashMod);
			parent.movement.dashTimer = baseDashMod.modValue;
		}
		inputVector = GetInputVector();
		initInputVec = inputVector;
		parent.movement.dashVector = inputVector;
		parent.anim.PlayDirectional(parent.DashAnimStr);
		parent.TogglePreventFallCollider(status: false);
		parent.ToggleEnemyFloorCollisions(status: false);
		particleCounter = baseParticleCount;
		currentRotation = Globals.GetRotationVector(-inputVector);
		currentAtkObj = UnityEngine.Object.Instantiate(Attack.CirclePrefab, parent.attackOriginTrans.position, Quaternion.identity, parent.attackOriginTrans);
		currentAtk = currentAtkObj.GetComponent<Attack>();
		currentAtk.SetAttackInfo(parent.skillCategory, skillID, (!isUltimate) ? 1 : 5, isUltimate);
		Attack attack = currentAtk;
		attack.entityCollisionEventHandlers = (Attack.EntityCollisionEventHandler)Delegate.Remove(attack.entityCollisionEventHandlers, new Attack.EntityCollisionEventHandler(SetHitTarget));
		Attack attack2 = currentAtk;
		attack2.entityCollisionEventHandlers = (Attack.EntityCollisionEventHandler)Delegate.Combine(attack2.entityCollisionEventHandlers, new Attack.EntityCollisionEventHandler(SetHitTarget));
		currentAtk.knockbackOverwriteVector = inputVector;
		targetHit = false;
		targetIsAlive = false;
		targetEntity = null;
		targetGrabbed = false;
		targetCanBeMoved = false;
