	{
		if (!finishedDashing)
		{
			return;
		}
		if (!targetHit)
		{
			fsm.ChangeState(SlideState.staticID);
			return;
		}
		if (targetIsAlive && (targetEntity == null || targetEntity.currentStateName == "Dead" || targetEntity.hurtBoxTransform == null || targetEntity.rigidbody2D == null))
		{
			targetIsAlive = false;
			comboFinished = true;
			finalAttackFinished = true;
			comboStopwatchID = ChaosStopwatch.Begin(exitDelay);
