public class UseBlazingCombo : ProjectileAttackState
{
	public new static string staticID = "UseBlazingCombo";
	private BlazingComboProjectile currentBC;
	private ChaosQuickStopwatch delayStopwatch = new ChaosQuickStopwatch(0.08f);
	private bool delayStarted;
	private bool delayCompleted;
	private bool targetHit;
	private bool targetStop;
	private int comboCountMax = 4;
	private int comboCounter;
	public override string OnEnterAnimStr => parent.ForehandAnimStr;
	private Vector2 HoldPosition => (Vector2)parent.attackOriginTrans.position - inputVector * 0.25f;
	public UseBlazingCombo(FSM parentFSM, Player parentEntity)
		: base(staticID, parentFSM, parentEntity)
	{
		isMovementSkill = true;
		SetAnimTimes(0.1f, 0.2f, 0.25f, 0.7f, 0.9f);
	}
	public override void SetEmpowered(bool givenStatus, BoolVarStatMod givenMod)
	{
		base.SetEmpowered(givenStatus, givenMod);
		comboCountMax = ((!IsEmpowered) ? 4 : 5);
	}
	public override void OnEnter()
	{
		base.OnEnter();
		delayStarted = false;
		delayCompleted = false;
		targetHit = false;
		targetStop = false;
		comboCounter = 0;
	}
	public override void ExecuteSkill()
	{
		if (!delayStarted)
		{
			delayStarted = true;
			delayStopwatch.SetDelay(0.08f, stopCurrent: false, autoStart: true);
			parent.ToggleEnemyFloorCollisions(status: false);
			parent.movement.moveVector = inputVector;
			parent.movement.MoveToMoveVector(60f);
			CreateCombo(isPrimary: true);
		}
		if (!delayCompleted && delayStopwatch.IsRunning)
		{
			if (comboCounter == 0)
			{
				parent.anim.PlayDirectional(OnEnterAnimStr, -1, animExecTime);
			}
			else
			{
				CancelToDash();
			}
			return;
		}
		if (comboCounter < comboCountMax)
		{
			if (comboCounter == 0)
			{
				ThrowCombo(isFinal: false);
				parent.movement.EndMovement();
				parent.movement.MoveToMoveVector(10f);
			}
			comboCounter++;
			if (comboCounter == 1)
			{
				parent.anim.PlayDirectional(parent.LastHandAnimStr, -1, 0.3f);
				delayStopwatch.SetDelay((!IsEmpowered) ? 0.15f : 0.1f);
			}
			else
			{
				parent.anim.PlayDirectional(parent.NextHandAnimStr, -1, 0.3f);
				CreateCombo();
				ThrowCombo(comboCounter == comboCountMax);
			}
			if (comboCounter <= comboCountMax)
			{
				delayStopwatch.IsRunning = true;
				return;
			}
		}
		delayCompleted = true;
		parent.anim.PlayDirectional(parent.LastHandAnimStr, -1, 0.3f);
		base.ExecuteSkill();
	}
	public override void FixedUpdate()
	{
		if (!delayCompleted && currentBC != null)
		{
			currentBC.transform.position = HoldPosition;
		}
	}
	public override void OnExit()
	{
		base.OnExit();
		parent.movement.EndMovement();
		parent.ToggleEnemyFloorCollisions();
		if (currentBC != null)
		{
			currentBC.ResetProjectile();
		}
	}
	private void CreateCombo(bool isPrimary = false)
	{
		currentBC = (BlazingComboProjectile)CreateProjectile(BlazingComboProjectile.Prefab, HoldPosition, Globals.GetRotationQuaternion(inputVector));
		currentBC.targetVector = inputVector;
		currentBC.attackBox.knockbackOverwriteVector = inputVector;
		if (isPrimary)
		{
			currentBC.grabTargets = true;
			currentBC.attackBox.SetAttackInfo(parent.skillCategory, skillID, 2);
			Attack attackBox = currentBC.attackBox;
			attackBox.entityCollisionEventHandlers = (Attack.EntityCollisionEventHandler)Delegate.Remove(attackBox.entityCollisionEventHandlers, new Attack.EntityCollisionEventHandler(OnTargetHit));
			Attack attackBox2 = currentBC.attackBox;
			attackBox2.entityCollisionEventHandlers = (Attack.EntityCollisionEventHandler)Delegate.Combine(attackBox2.entityCollisionEventHandlers, new Attack.EntityCollisionEventHandler(OnTargetHit));
		}
		else
		{
			currentBC.attackBox.SetAttackInfo(parent.skillCategory, skillID);
			currentBC.firePartSys.Stop();
		}
	}
	private void ThrowCombo(bool isFinal)
	{
		if (!(currentBC == null))
		{
			currentBC.attackBox.ChangeAttackInfoLevel(1);
			currentBC.SetBurstInfo(parent.skillCategory, skillID, (!isFinal) ? 2 : 3);
			currentBC.transform.position = parent.attackOriginTrans.position;
			currentBC.goThroughWalls = false;
			currentBC.disableOnHit = true;
			Attack attackBox = currentBC.attackBox;
			attackBox.entityCollisionEventHandlers = (Attack.EntityCollisionEventHandler)Delegate.Remove(attackBox.entityCollisionEventHandlers, new Attack.EntityCollisionEventHandler(OnTargetHit));
			currentBC.isFinal = isFinal;
			currentBC.grabTargets = false;
			FireProjectile(currentBC, inputVector, setKnockbackVector: true, 36f, (!targetStop) ? (0.08f + (float)comboCounter * 0.01f) : 0.01f, string.Empty);
			currentBC = null;
			if (isFinal)
			{
				CameraController.ShakeCamera(0.25f);
			}
		}
	}
	private void OnTargetHit(Entity givenEntity)
	{
		if (!(givenEntity == null) && !(givenEntity is Destructible))
		{
			targetHit = true;
			if (givenEntity.health.ignoreGrab)
			{
				parent.movement.EndMovement();
				targetStop = true;
			}
		}
	}
}

using System;
using System.Collections.Generic;
using UnityEngine;
public class BlazingComboProjectile : Projectile
{
	private static GameObject prefab;
	public ParticleSystem firePartSys;
	public Vector2 targetVector;
	private string burstCategory = string.Empty;
	private string burstID = string.Empty;
	private int burstLevel;
	public bool grabTargets;
	private Vector2 dragVector;
	private float dragMaxDist = 3f;
	private List<Entity> hitList = new List<Entity>();
	private Entity tempEnt;
	public bool isFinal;
	public static GameObject Prefab => prefab ?? (prefab = ChaosBundle.Get("Assets/Prefabs/Projectiles/BlazingComboProjectile.prefab"));
	public override void Start()
	{
		base.Start();
		if (isFinal)
		{
			anim.Play("IdleFinal");
		}
		if (grabTargets)
		{
			Attack attack = attackBox;
			attack.entityCollisionEventHandlers = (Attack.EntityCollisionEventHandler)Delegate.Remove(attack.entityCollisionEventHandlers, new Attack.EntityCollisionEventHandler(OnTargetHit));
			Attack attack2 = attackBox;
			attack2.entityCollisionEventHandlers = (Attack.EntityCollisionEventHandler)Delegate.Combine(attack2.entityCollisionEventHandlers, new Attack.EntityCollisionEventHandler(OnTargetHit));
		}
		string audioID = "FireballCast";
		Vector2? soundOrigin = transform.position;
		float overridePitch = UnityEngine.Random.Range(0.9f, 1f);
		SoundManager.PlayAudioWithDistance(audioID, soundOrigin, null, 24f, -1f, overridePitch);
	}
	public override void FixedUpdate()
	{
		base.FixedUpdate();
		if (!grabTargets)
		{
			return;
		}
		dragVector = targetVector * moveSpeed;
		for (int num = hitList.Count - 1; num >= 0; num--)
		{
			tempEnt = hitList[num];
			if (tempEnt == null || tempEnt.rigidbody2D == null || tempEnt.hurtBoxTransform == null || Vector2.Distance(tempEnt.hurtBoxTransform.position, transform.position) > dragMaxDist)
			{
				hitList.RemoveAt(num);
			}
			else
			{
				tempEnt.rigidbody2D.velocity = dragVector;
			}
		}
	}
	public override void ResetProjectile()
	{
		Attack attack = attackBox;
		attack.entityCollisionEventHandlers = (Attack.EntityCollisionEventHandler)Delegate.Remove(attack.entityCollisionEventHandlers, new Attack.EntityCollisionEventHandler(OnTargetHit));
		FlameBurst.CreateBurst(transform.position, burstCategory, burstID, burstLevel, (!isFinal) ? 1.25f : 2f).attack.knockbackOverwriteVector = moveVector;
		if (firePartSys != null)
		{
			firePartSys.transform.SetParent(transform.parent);
			firePartSys.Stop();
			UnityEngine.Object.Destroy(firePartSys.gameObject, 1f);
		}
		SoundManager.PlayWithDistAndSPR("BlazingBlitzEnd", transform.position);
		base.ResetProjectile();
	}
	public void SetBurstInfo(string givenCategory, string givenID, int givenLevel)
	{
		burstCategory = givenCategory;
		burstID = givenID;
		burstLevel = givenLevel;
	}
	private void OnTargetHit(Entity givenEntity)
	{
		if (!(givenEntity == null) && !(givenEntity is Destructible) && !hitList.Contains(givenEntity) && !(givenEntity.rigidbody2D == null) && givenEntity.rigidbody2D.bodyType == RigidbodyType2D.Dynamic && !(givenEntity.health == null) && !givenEntity.health.ignoreGrab)
		{
			hitList.Add(givenEntity);
		}
	}
}

	public class SummonHomingMissilesState : ProjectileAttackState
	{
		public new static string staticID = "SummonHomingMissiles";
		private HomingMissile currentHM;
		private int spawnCount = 7;
		private float duration = 2.75f;
		private float homingRadius = 5f;
		private List<HomingMissile> hmList = new List<HomingMissile>();
		private ChaosQuickStopwatch durationStopwatch = new ChaosQuickStopwatch(3f);
		private ChaosQuickStopwatch intervalStopwatch = new ChaosQuickStopwatch(0.125f);
		private Vector2 currentPosition;
		private Vector2 seedVector;
		private const int SeedMax = 6;
		private int seedValue;
		public override string OnEnterAnimStr => parent.PBAoEAnimStr;
		public SummonHomingMissilesState(FSM parentFSM, Player parentEntity)
			: base(staticID, parentFSM, parentEntity)
		{
			hasSignatureVariant = true;
			SetAnimTimes(0.1f);
		}
		public override void SetEmpowered(bool givenStatus, BoolVarStatMod givenMod)
		{
			base.SetEmpowered(givenStatus, givenMod);
			if (IsEmpowered)
			{
				spawnCount = 10;
				duration = 4f;
			}
			else
			{
				spawnCount = 7;
				duration = 2.75f;
			}
		}
		public override void OnEnter()
		{
			base.OnEnter();
			homingRadius = ((!isUltimate) ? 5f : 7f);
		}
		public override void ExecuteSkill()
		{
			base.ExecuteSkill();
			SoundManager.PlayWithDistAndSPR("HomingMissile", parent.transform.position);
			CameraController.ShakeCamera(0.25f);
			if (isUltimate)
			{
				parent.StartCoroutine(CreateHomingCloud());
			}
			else
			{
				CreateHomingRing(spawnCount);
			}
		}
		private void CreateHomingRing(int givenCount, bool addToList = false)
		{
			currentPosition = parent.attackOriginTrans.position;
			seedVector = UnityEngine.Random.insideUnitCircle.normalized;
			for (int i = 0; i < givenCount; i++)
			{
				CreateHomingMissile(currentPosition, Globals.GetRotatedCircleVector(givenCount, i, seedVector), addToList);
			}
		}
		private void CreateHomingMissile(Vector2 givenPosition, Vector2 givenVector, bool addToList = false)
		{
			currentHM = (HomingMissile)CreateProjectile(HomingMissile.Prefab, givenPosition + givenVector);
			currentHM.InitOrbitVars(givenVector, duration, homingRadius);
			if (addToList)
			{
				hmList.Add(currentHM);
				currentHM.attackBox.atkInfo.isUltimate = true;
			}
		}
		private void CleanUpList()
		{
			for (int num = hmList.Count - 1; num >= 0; num--)
			{
				if (hmList[num] == null || !hmList[num].orbitMode)
				{
					hmList.RemoveAt(num);
				}
			}
		}
		private void ResetList()
		{
			for (int num = hmList.Count - 1; num >= 0; num--)
			{
				if (hmList[num] != null)
				{
					hmList[num].ResetProjectile();
				}
			}
			hmList.Clear();
		}
		private IEnumerator CreateHomingCloud()
		{
			parent.hud.castBar.EndCast();
			yield return null;
			if (durationStopwatch.IsRunning)
			{
				durationStopwatch.IsRunning = true;
				parent.hud.castBar.StartCast(durationStopwatch.ID, givenStatus: false);
				CreateHomingRing(spawnCount, addToList: true);
				yield break;
			}
			ResetList();
			yield return null;
			durationStopwatch.IsRunning = true;
			parent.hud.castBar.StartCast(durationStopwatch.ID, givenStatus: false);
			CreateHomingRing(spawnCount, addToList: true);
			seedValue = UnityEngine.Random.Range(0, 6);
			while (durationStopwatch.IsRunning)
			{
				if (!intervalStopwatch.IsRunning)
				{
					intervalStopwatch.IsRunning = true;
					seedValue++;
					CleanUpList();
					if (hmList.Count < spawnCount)
					{
						CreateHomingMissile(parent.attackOriginTrans.position, Globals.GetCirclePositionVector(6, seedValue), addToList: true);
					}
				}
				yield return null;
			}
			parent.hud.castBar.EndCast();
		}
	}
