			currentFR.moveSpeed *= Mathf.Lerp(1f, 1.25f, varsLerpValue);
			currentFR.flyTime = Mathf.Lerp(0.625f, 0.75f, varsLerpValue);
			currentFR.moveBias = Mathf.Lerp(2f, 1f, varsLerpValue);
			currentFR.positiveArc = givenArc;
			FireProjectile(currentFR, inputVector, setKnockbackVector: true, 0f, 0f, string.Empty);
			FireBurst fireBurst = fireEmitter;
			int? particleCount = 3;
			Vector3? position = givenPosition;
			Vector3? localEulerAngles = rotationVec;
