	public Transform parentTrans;
	public bool positiveArc;
	private float initMoveSpeed;
	private float finalMoveSpeed;
	private ChaosQuickStopwatch arcStopwatch = new ChaosQuickStopwatch(0f);
	private bool arcSign;
	private float arcLerpValue;
	public float arcBias = 0.5f;
	public float moveBias = 0.75f;
	public float returnBias = 0.25f;
	private Vector2 calcVector;
	private Vector2 prevVector;
	private Vector2 initMoveVector;
	private Vector2 rightBound;
	private Vector2 leftBound;
	private float roteAngle;
	public bool ignoreArc;
	public bool quickArc;
	private ParticleSystem firePartSys;
	private ParticleSystem.MainModule firePartSysMain;
