	public override void Awake()
	{
		base.Awake();
		firePartSys = transform.Find("FirePartSys").GetComponent<ParticleSystem>();
		firePartSysMain = firePartSys.main;
	}
	public override void Start()
	{
		base.Start();
		InitArcVars();
		Attack attack = attackBox;
		attack.attackCollisionEventHandlers = (Attack.AttackCollisionEventHandler)Delegate.Remove(attack.attackCollisionEventHandlers, new Attack.AttackCollisionEventHandler(OnTargetHit));
		Attack attack2 = attackBox;
		attack2.attackCollisionEventHandlers = (Attack.AttackCollisionEventHandler)Delegate.Combine(attack2.attackCollisionEventHandlers, new Attack.AttackCollisionEventHandler(OnTargetHit));
		if (isEmpowered)
		{
			firePartSysMain.startSize = 1.1f;
			attackBox.GetComponent<CircleCollider2D>().radius *= 1.25f;
			projectileSpriteRenderer.sprite = largeSprite;
		}
		SoundManager.PlayAudioWithDistance("FireArcStart", transform.position);
	}
	public override void Update()
	{
		if (CheckMaxLifeTime())
		{
			return;
		}
		if (ChaosStopwatch.Check(flyStopwatchID))
		{
			if (!boomerangReturning)
			{
				boomerangReturning = true;
			}
			if (parentTrans == null || Vector2.Distance(transform.position, parentTrans.position) < returningSnapDistance)
			{
				ResetProjectile();
				return;
			}
		}
		if (attackBox != null)
		{
			attackBox.knockbackOverwriteVector = moveVector;
		}
		transform.localEulerAngles = Globals.GetRotationVector(moveVector);
	}
	public override void FixedUpdate()
	{
		base.FixedUpdate();
		if (!boomerangReturning)
		{
			arcLerpValue = arcStopwatch.TimePercentage;
			moveSpeed = Mathf.Lerp(initMoveSpeed, finalMoveSpeed, (!arcSign) ? arcLerpValue : (1f - arcLerpValue));
