				calcVector = initMoveVector * moveBias + Vector2.Lerp(leftBound, rightBound, arcLerpValue) * arcBias;
				moveVector = (moveVector + calcVector).normalized;
			}
			if (!arcSign && arcLerpValue >= 1f)
			{
				arcSign = true;
				arcStopwatch.IsRunning = true;
				initMoveVector *= -1f;
				SetBounds(initMoveVector);
				attackBox.ChangeAttackInfoLevel(attackBox.atkInfo.skillLevel + 1);
				goThroughWalls = true;
				ignoreArc = false;
			}
		}
		else if (parentTrans != null)
		{
			calcVector = (parentTrans.position - transform.position).normalized * returnBias;
			prevVector = moveVector;
			moveVector = (moveVector + calcVector).normalized;
			moveSpeed = Mathf.Lerp(initMoveSpeed, finalMoveSpeed, Mathf.Clamp01(Vector2.Angle(prevVector, moveVector) * 0.25f));
		}
	}
	public override void HandleWallCollision(Collider2D other)
	{
		base.HandleWallCollision(other);
		if (quickArc)
		{
			quickArc = false;
			returnBias *= 10f;
		}
	}
	public override void ResetProjectile()
	{
		if (firePartSys != null && firePartSys.gameObject != null)
		{
			firePartSysMain.startSpeed = 5f;
			firePartSys.Emit(5);
			firePartSys.Stop();
			firePartSys.transform.SetParent(null);
			UnityEngine.Object.Destroy(firePartSys.gameObject, 0.5f);
		}
		SoundManager.PlayAudioWithDistance("FireBlastODEnd", transform.position);
		Attack attack = attackBox;
		attack.attackCollisionEventHandlers = (Attack.AttackCollisionEventHandler)Delegate.Remove(attack.attackCollisionEventHandlers, new Attack.AttackCollisionEventHandler(OnTargetHit));
		base.ResetProjectile();
	}
	private void InitArcVars()
	{
		arcStopwatch.SetDelay(flyTime * 0.6f, stopCurrent: false, autoStart: true);
		initMoveSpeed = moveSpeed * 1.5f;
		finalMoveSpeed = moveSpeed;
		initMoveVector = moveVector;
		SetBounds(initMoveVector);
	}
	private void SetBounds(Vector2 givenVector)
	{
		roteAngle = Vector3.Angle(Vector3.up, givenVector) * ((float)Math.PI / 180f) * ((!(givenVector.x > 0f)) ? 1f : (-1f));
		if (positiveArc)
		{
			rightBound = new Vector2(Mathf.Cos(roteAngle), Mathf.Sin(roteAngle)).normalized;
			roteAngle += (float)Math.PI;
			leftBound = new Vector2(Mathf.Cos(roteAngle), Mathf.Sin(roteAngle)).normalized;
		}
		else
		{
			leftBound = new Vector2(Mathf.Cos(roteAngle), Mathf.Sin(roteAngle)).normalized;
			roteAngle += (float)Math.PI;
			rightBound = new Vector2(Mathf.Cos(roteAngle), Mathf.Sin(roteAngle)).normalized;
		}
	}
	private void OnTargetHit(Collider2D col = null)
	{
		FireExplosion.SpawnExplosion(transform.position, 0.5f, 0.5f, 5, 5);
	}
}

	public class ProjectileChainAttackState : ProjectileAttackState
	{
		public float shotDelay = 0.125f;
		public int shotStopwatchID;
		public bool attackStarted;
		public bool firstAnim;
		public bool updateInput = true;
		private Vector2 checkAimVec;
		public ProjectileChainAttackState(string newName, FSM newFSM, Player newPlayer)
			: base(newName, newFSM, newPlayer)
		{
			disableStartCooldown = true;
			isHoldSkill = true;
			InitChargeSkillSettings(skillData.GetValue<int>(StatData.spawnStr), 0f, skillData, this);
		}
		public override void OnEnter()
		{
			base.OnEnter();
			UpdateCDCounter();
			attackStarted = false;
			firstAnim = true;
		}
		public override void HandleHoldButton()
		{
			if (!StartAttack())
			{
				return;
			}
			switch (ChaosStopwatch.CheckInterval(shotStopwatchID))
			{
			case StopwatchState.Ready:
				if (firstAnim)
				{
					firstAnim = false;
					AnnounceSkillExecuteEvent();
				}
				else if (updateInput)
				{
					checkAimVec = GetInputVector(faceInputVector: false, useAimVector: true, ignoreZero: false);
					if (checkAimVec != Vector2.zero)
					{
						inputVector = GetInputVector(faceInputVector: true, useAimVector: true, ignoreZero: false);
					}
					parent.anim.PlayDirectional(OnHoldAnimStr, -1, animExecTime);
				}
				if (cooldownRef.chargeCount > 0)
				{
					cooldownRef.chargeCount--;
				}
				if (!cooldownRef.IsCharging)
				{
					UpdateCDCounter();
				}
				FireChainProjectile();
				break;
			case StopwatchState.Done:
				skillExecuted = true;
				break;
			}
			CancelToDash();
		}
		public override void OnExit()
		{
			base.OnExit();
			StartCooldownTimer(-1f, expendCharge: false);
			ChaosStopwatch.Stop(shotStopwatchID);
		}
		public virtual void UpdateCDCounter()
		{
			StartCooldownTimer(-1f, expendCharge: false);
			ChaosStopwatch.Pause(cooldownRef.remainingTimeStopwatchID);
		}
		public virtual bool StartAttack()
		{
			if (!attackStarted)
			{
				if (!parent.anim.AnimPlayed(animExecTime))
				{
					return false;
				}
				attackStarted = true;
				shotStopwatchID = ChaosStopwatch.Begin(0f, useInterval: true, shotDelay, cooldownRef.chargeCount);
			}
			return true;
		}
		public virtual void FireChainProjectile()
		{
		}
	}
