	public void HandleSkillUnlock(SkillState givenSkill, bool isSignature)
	{
		if (givenSkill != null)
		{
			bool flag = false;
			bool flag2 = false;
			if (!givenSkill.isUnlocked)
			{
				givenSkill.isUnlocked = true;
				flag = true;
			}
			if (isSignature && givenSkill.hasSignatureVariant && !givenSkill.signatureUnlocked)
			{
				givenSkill.signatureUnlocked = true;
				flag2 = true;
			}
			if (flag2 || flag)
			{
				GameController.unlockNotifier.Notify(givenSkill.skillID, isSignature ? UnlockNotifier.NoticeType.Signature : UnlockNotifier.NoticeType.Spell);
				GameDataManager.Save();
				GameDataManager.gameData.PullSkillData();
				AchievementManager.UnlockAchievement(Achievement.UnlockHalfArcana);
				AchievementManager.UnlockAchievement(Achievement.UnlockAllArcana);
				SpellBookUI.SkillEquipType skillEquipType = ((!givenSkill.isBasic) ? (givenSkill.isDash ? SpellBookUI.SkillEquipType.Dash : ((!isSignature) ? SpellBookUI.SkillEquipType.Optional : SpellBookUI.SkillEquipType.Signature)) : SpellBookUI.SkillEquipType.Basic);
				NewSpellManager.Add(givenSkill.skillID, givenSkill.element, flag, flag2, skillEquipType, this);
			}
		}
	}

